:150,"rir":2,"unilateral":false,"note":null,"alternatives":[{"exerciseId":"Dumbbell_Shoulder_Press","name":"Dumbbell Shoulder Press"},{"exerciseId":"Machine_Shoulder_Military_Press","name":"Machine Shoulder (Military) Press"},{"exerciseId":"Standing_Military_Press","name":"Standing Military Press"},{"exerciseId":"Smith_Machine_Overhead_Shoulder_Press","name":"Smith Machine Overhead Shoulder Press"}],"contributions":{"triceps":0.5,"shoulders":0.5}},{"exerciseId":"Wide-Grip_Lat_Pulldown","name":"Wide-Grip Lat Pulldown","slot":"vertical_pull","pattern":"vertical_pull","sets":5,"reps":"6-10","repsMin":6,"repsMax":10,"timed":false,"restSeconds":150,"rir":2,"unilateral":false,"note":null,"alternatives":[{"exerciseId":"Close-Grip_Front_Lat_Pulldown","name":"Close-Grip Front Lat Pulldown"},{"exerciseId":"startfit:assisted-pull-up-machine","name":"Assisted Pull-Up (Machine)"},{"exerciseId":"Pullups","name":"Pullups"},{"exerciseId":"Chin-Up","name":"Chin-Up"}],"contributions":{"back":1,"biceps":0.5,"shoulders":0.5}},{"exerciseId":"catalog:bulgarian-split-squat","name":"Bulgarian Split Squat","slot":"quad_unilateral","pattern":"lunge","sets":4,"reps":"8-12 each side","repsMin":8,"repsMax":12,"timed":false,"restSeconds":90,"rir":2,"unilateral":true,"note":null,"alternatives":[{"exerciseId":"Dumbbell_Rear_Lunge","name":"Dumbbell Rear Lunge"},{"exerciseId":"Split_Squat_with_Dumbbells","name":"Split Squat with Dumbbells"},{"exerciseId":"Dumbbell_Step_Ups","name":"Dumbbell Step Ups"},{"exerciseId":"Barbell_Lunge","name":"Barbell Lunge"}],"contributions":{"quads":1,"glutes":1,"adductors":0.5}},{"exerciseId":"Standing_Calf_Raises","name":"Standing Calf Raises","slot":"calves","pattern":"calf_raise","sets":4,"reps":"10-15","repsMin":10,"repsMax":15,"timed":false,"restSeconds":75,"rir":1,"unilateral":false,"note":null,"alternatives":[{"exerciseId":"Seated_Calf_Raise","name":"Seated Calf Raise"},{"exerciseId":"Calf_Press_On_The_Leg_Press_Machine","name":"Calf Press On The Leg Press Machine"},{"exerciseId":"Smith_Machine_Calf_Raise","name":"Smith Machine Calf Raise"},{"exerciseId":"Standing_Dumbbell_Calf_Raise","name":"Standing Dumbbell Calf Raise"}],"contributions":{"calves":1}}],"warmup":"About 5 minutes of easy movement, then 1–2 lighter practice sets of the first lift before the working sets.","estimatedMinutes":75}],"volume":[{"group":"chest","label":"Chest","sets":10,"low":10,"high":16,"status":"in_range","priority":false},{"group":"back","label":"Back (lats & mid-back)","sets":10,"low":10,"high":16,"status":"in_range","priority":false},{"group":"shoulders","label":"Shoulders (side & rear)","sets":6.5,"low":10,"high":16,"status":"low","priority":false},{"group":"biceps","label":"Biceps","sets":5,"low":9,"high":14,"status":"low","priority":false},{"group":"triceps","label":"Triceps","sets":6.5,"low":9,"high":14,"status":"low","priority":false},{"group":"quads","label":"Quadriceps","sets":9,"low":10,"high":16,"status":"low","priority":false},{"group":"hamstrings","label":"Hamstrings","sets":9,"low":9,"high":14,"status":"in_range","priority":false},{"group":"glutes","label":"Glutes","sets":14,"low":9,"high":18,"status":"in_range","priority":false},{"group":"calves","label":"Calves","sets":4,"low":7,"high":11,"status":"low","priority":false},{"group":"abs","label":"Abs & obliques","sets":3,"low":7,"high":11,"status":"low","priority":false},{"group":"lower_back","label":"Lower back","sets":5,"low":0,"high":0,"status":"in_range","priority":false},{"group":"forearms","label":"Forearms","sets":2.5,"low":0,"high":0,"status":"in_range","priority":false},{"group":"adductors","label":"Adductors","sets":4.5,"low":0,"high":0,"status":"in_range","priority":false}],"progression":[{"week":1,"label":"Learn the plan","setsNote":"Planned sets","rirNote":"One repetition more in reserve than planned while you find your weights"},{"week":2,"label":"Build","setsNote":"Planned sets","rirNote":"Planned reps in reserve; add repetitions where you can"},{"week":3,"label":"Build","setsNote":"Planned sets","rirNote":"Planned reps in reserve; add weight where you hit the top of the range"},{"week":4,"label":"Build","setsNote":"Planned sets","rirNote":"Planned reps in reserve"},{"week":5,"label":"Build or lighter week","setsNote":"If you feel run down or performance dropped: about half the sets","rirNote":"Lighter week: easy loads, 4+ repetitions in reserve"},{"week":6,"label":"Re-test and rebuild","setsNote":"Rebuild the plan with your new numbers","rirNote":"Planned reps in reserve"}],"progressionRules":["Double progression: keep the weight until you reach the top of the repetition range on every set at the planned effort, then add the smallest step the equipment allows. Adding repetitions or adding weight both work.","If you can do 1–2 repetitions more than the planned number, increase the load by about 2–10%.","Log every set with its repetitions in reserve. If performance drops for two sessions in a row, or you feel run down, take the lighter week early.","Rebuild the plan every 6–8 weeks, or sooner if your goal, schedule, equipment or health changes."],"cardio":[{"mode":"walking","label":"Brisk or incline walking","minutes":40,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":1,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":40,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":2,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":4,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":5,"note":"Moderate effort: you can talk but not sing."}],"cardioMinutesPerWeek":150,"cardioTargetMinutes":150,"cardioRamp":[150,150,150,150,150,150],"notes":[{"kind":"adjustment","text":"Shoulders (side & rear), Biceps, Triceps, Quadriceps, Calves, Abs & obliques are below the weekly target because the sessions are full. More minutes per session or another training day would close the gap."}],"claimIds":["acsm_days","vol_fractional","vol_dose","vol_session_cap","vol_targets_design","exercise_order","warmup","load_range","failure_optional","failure_proximity","rir_scale","rest_hypertrophy","freq_hypertrophy","progress_both","progress_increase","deload_concept","deload_rule","who_activity","concurrent"],"rationale":[{"claimId":"acsm_days","decision":"2 strength days a week, matching the time you have."},{"claimId":"vol_fractional","decision":"Weekly sets are counted as 1 for the main muscle and ½ for helping muscles, and each muscle group gets a target range."},{"claimId":"vol_dose","decision":"Targets for your level are 10–16 weekly sets for the big muscle groups (fewer for calves and abs)."},{"claimId":"exercise_order","decision":"Each session starts with the big multi-joint lifts and ends with smaller single-joint and core exercises."},{"claimId":"warmup","decision":"Every session starts with a short general warm-up and lighter practice sets."},{"claimId":"load_range","decision":"Main lifts use 6–10 repetitions and smaller exercises use higher repetitions; lighter and heavier loads both build muscle."},{"claimId":"failure_optional","decision":"Sets stop about 2 repetitions short of failure on the main lifts; training to failure is not required."},{"claimId":"failure_proximity","decision":"Smaller exercises go a little closer to failure (about 1–2 repetitions in reserve) because growth tends to improve closer to failure."},{"claimId":"rest_hypertrophy","decision":"Rest about 2.5 minutes after main-lift sets and 75 seconds after smaller exercises."},{"claimId":"freq_hypertrophy","decision":"Each major muscle group is trained on at least two days, spreading the weekly sets so each session stays manageable."},{"claimId":"progress_both","decision":"Progress by adding repetitions first, then weight (double progression)."},{"claimId":"progress_increase","decision":"Load increases of about 2–10% once you can do 1–2 repetitions more than planned."},{"claimId":"deload_concept","decision":"A lighter week is planned as an option, used when tiredness or performance call for it."},{"claimId":"who_activity","decision":"150 minutes of cardio a week, inside the WHO range of 150–300."},{"claimId":"concurrent","decision":"Cardio goes on other days or at least a few hours away from lifting where possible, so it does not blunt your strength sessions."}],"inputs":{"goal":"muscle","experience":"intermediate","daysPerWeek":2,"sessionMinutes":75,"equipment":["bodyweight","dumbbell","barbell","ez_bar","rack","bench","kettlebell","cable","machine","smith_machine","band","pullup_bar","dip_bars","trap_bar","landmine","medicine_ball","exercise_ball","foam_roller","ab_wheel","box","rings","suspension","sled","strongman","cardio_machine","other"],"age":30,"pain":[],"priorityMuscles":[],"currentActivity":"regular","screeningStatus":"ok"}}'::jsonb, 'library')
