{"week":6,"label":"Re-test and rebuild","setsNote":"Rebuild the plan with your new numbers","rirNote":"Planned reps in reserve"}],"progressionRules":["Double progression: keep the weight until you reach the top of the repetition range on every set at the planned effort, then add the smallest step the equipment allows. Adding repetitions or adding weight both work.","If you can do 1–2 repetitions more than the planned number, increase the load by about 2–10%.","Log every set with its repetitions in reserve. If performance drops for two sessions in a row, or you feel run down, take the lighter week early.","Rebuild the plan every 6–8 weeks, or sooner if your goal, schedule, equipment or health changes."],"cardio":[{"mode":"walking","label":"Brisk or incline walking","minutes":40,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":0,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":40,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":2,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":5,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":6,"note":"Moderate effort: you can talk but not sing."}],"cardioMinutesPerWeek":150,"cardioTargetMinutes":150,"cardioRamp":[150,150,150,150,150,150],"notes":[],"claimIds":["acsm_days","vol_fractional","vol_dose","vol_session_cap","vol_targets_design","exercise_order","warmup","load_range","failure_optional","failure_proximity","rir_scale","rest_hypertrophy","freq_hypertrophy","progress_both","progress_increase","deload_concept","deload_rule","who_activity","concurrent"],"rationale":[{"claimId":"acsm_days","decision":"4 strength days a week, matching the ti