},{"week":4,"label":"Build","setsNote":"Planned sets","rirNote":"Planned reps in reserve"},{"week":5,"label":"Build or lighter week","setsNote":"If you feel run down or performance dropped: about half the sets","rirNote":"Lighter week: easy loads, 4+ repetitions in reserve"},{"week":6,"label":"Re-test and rebuild","setsNote":"Rebuild the plan with your new numbers","rirNote":"Planned reps in reserve"}],"progressionRules":["Double progression: keep the weight until you reach the top of the repetition range on every set at the planned effort, then add the smallest step the equipment allows. Adding repetitions or adding weight both work.","If you can do 1–2 repetitions more than the planned number, increase the load by about 2–10%.","Log every set with its repetitions in reserve. If performance drops for two sessions in a row, or you feel run down, take the lighter week early.","Rebuild the plan every 6–8 weeks, or sooner if your goal, schedule, equipment or health changes."],"cardio":[{"mode":"walking","label":"Brisk or incline walking","minutes":40,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":0,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":40,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":2,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":5,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":6,"note":"Moderate effort: you can talk but not sing."}],"cardioMinutesPerWeek":150,"cardioTargetMinutes":150,"cardioRamp":[150,150,150,150,150,150],"notes":[{"kind":"adjustment","text":"Chest, Shoulders (side & rear) are below the weekly target because the sessions are full. More minutes per session or another training day would close the gap."}],"claimIds":["acsm_days","vol_fractional","vol_dose","vol_session_cap","vol_targets_design","exercise_order","warmup","load_range","failure_optional","failure_proximity","rir_scale","rest_hypertrophy","freq_hypertrophy","progress_both","progress_increase","deload_concept","deload_rule","who_activity","concurrent"],"rationale":[{"claimId":"acsm_days","decision":"4 strength days a week, matching the time you have."},{"claimId":"vol_fractional","decision":"Weekly sets are counted as 1 for the main muscle and ½ for helping muscles, and each muscle group gets a target range."},{"claimId":"vol_dose","decision":"Targets for your level are 10–16 weekly sets for the big muscle groups (fewer for calves and abs)."},{"claimId":"exercise_order","decision":"Each session starts with the big multi-joint lifts and ends with smaller single-joint and core exercises."},{"claimId":"warmup","decision":"Every session starts with a short general warm-up and lighter practice sets."},{"claimId":"load_range","decision":"Main lifts use 6–10 repetitions and smaller exercises use higher repetitions; lighter and heavier loads both build muscle."},{"claimId":"failure_optional","decision":"Sets stop about 2 repetitions short of failure on the main lifts; training to failure is not required."},{"claimId":"failure_proximity","decision":"Smaller exercises go a little closer to failure (about 1–2 repetitions in reserve) because growth tends to improve closer to failure."},{"claimId":"rest_hypertrophy","decision":"Rest about 2.5 minutes after main-lift sets and 75 seconds after smaller exercises."},{"claimId":"freq_hypertrophy","decision":"Each major muscle group is trained on at least two days, spreading the weekly sets so each session stays manageable."},{"claimId":"progress_both","decision":"Progress by adding repetitions first, then weight (double progression)."},{"claimId":"progress_increase","decision":"Load increases of about 2–10% once you can do 1–2 repetitions more than planned."},{"claimId":"deload_concept","decision":"A lighter week is planned as an option, used when tiredness or performance call for it."},{"claimId":"who_activity","decision":"150 minutes of cardio a week, inside the WHO range of 150–300."},{"claimId":"concurrent","decision":"Cardio goes on other days or at least a few hours away from lifting where possible, so it does not blunt your strength sessions."}],"inputs":{"goal":"muscle","experience":"intermediate","daysPerWeek":4,"sessionMinutes":60,"equipment":["bodyweight","dumbbell","barbell","ez_bar","rack","bench","kettlebell","band","pullup_bar","dip_bars","box","landmine"],"age":30,"pain":[],"priorityMuscles":[],"currentActivity":"regular","screeningStatus":"ok"}}'::jsonb, 'library')
