risk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":6,"note":"Moderate effort: you can talk but not sing."}],"cardioMinutesPerWeek":150,"cardioTargetMinutes":150,"cardioRamp":[150,150,150,150,150,150],"notes":[],"claimIds":["acsm_days","vol_fractional","vol_dose","vol_session_cap","vol_targets_design","exercise_order","warmup","load_range","failure_optional","rir_start_easier","rir_scale","rest_intervals","freq_strength","progress_both","progress_increase","deload_concept","deload_rule","who_activity","concurrent"],"rationale":[{"claimId":"acsm_days","decision":"3 strength days a week, matching the time you have."},{"claimId":"vol_fractional","decision":"Weekly sets are counted as 1 for the main muscle and ½ for helping muscles, and each muscle group gets a target range."},{"claimId":"vol_dose","decision":"Targets for your level are 6–10 weekly sets for the big muscle groups (fewer for calves and abs)."},{"claimId":"exercise_order","decision":"Each session starts with the big multi-joint lifts and ends with smaller single-joint and core exercises."},{"claimId":"warmup","decision":"Every session starts with a short general warm-up and lighter practice sets."},{"claimId":"load_range","decision":"Main lifts use 5–8 repetitions so the loads are heavy enough to build strength."},{"claimId":"failure_optional","decision":"Sets stop about 3 repetitions short of failure on the main lifts; training to failure is not required."},{"claimId":"rest_intervals","decision":"Rest about 1.5 minutes after main-lift sets and 60 seconds after smaller exercises."},{"claimId":"freq_strength","decision":"Each major muscle group is trained on at least two days, spreading the weekly sets so each session stays manageable."},{"claimId":"progress_both","decision":"Progress by adding repetitions first, then weight (double progression)."},{"claimId":"progress_increase","decision":"Load increases of about 2–10% once you can do 1–2 repetitions