osition results."},{"claimId":"concurrent","decision":"Cardio goes on other days or at least a few hours away from lifting where possible, so it does not blunt your strength sessions."},{"claimId":"rt_body_fat","decision":"Strength training stays the core of the plan while you lose fat."}],"inputs":{"goal":"fat_loss","experience":"beginner","daysPerWeek":3,"sessionMinutes":60,"equipment":["bodyweight","dumbbell","barbell","ez_bar","rack","bench","kettlebell","cable","machine","smith_machine","band","pullup_bar","dip_bars","trap_bar","landmine","medicine_ball","exercise_ball","foam_roller","ab_wheel","box","rings","suspension","sled","strongman","cardio_machine","other"],"age":30,"pain":[],"priorityMuscles":[],"currentActivity":"regular","screeningStatus":"ok"}}'::jsonb, 'library')
