unilateral":true,"note":null,"alternatives":[{"exerciseId":"Dumbbell_Incline_Row","name":"Dumbbell Incline Row"},{"exerciseId":"startfit:band-row","name":"Band Seated Row"}],"contributions":{"back":1,"biceps":0.5,"shoulders":0.5}},{"exerciseId":"Seated_Band_Hamstring_Curl","name":"Seated Band Hamstring Curl","slot":"hamstring_curl","pattern":"knee_flexion","sets":2,"reps":"10-15","repsMin":10,"repsMax":15,"timed":false,"restSeconds":60,"rir":3,"unilateral":false,"note":null,"alternatives":[{"exerciseId":"catalog:banded-leg-curl","name":"Banded Leg Curl"}],"contributions":{"hamstrings":1}}],"warmup":"About 5 minutes of easy movement, then 1–2 lighter practice sets of the first lift before the working sets.","estimatedMinutes":30},{"index":1,"label":"Day 2 · Full body B","focus":"Whole body: hinge, overhead press, pulldown","weekday":3,"exercises":[{"exerciseId":"startfit:dumbbell-romanian-deadlift","name":"Dumbbell Romanian Deadlift","slot":"hinge","pattern":"hinge","sets":2,"reps":"8-12","repsMin":8,"repsMax":12,"timed":false,"restSeconds":90,"rir":3,"unilateral":false,"note":null,"alternatives":[{"exerciseId":"catalog:kettlebell-deadlift","name":"Kettlebell Deadlift"},{"exerciseId":"Band_Good_Morning","name":"Band Good Morning"}],"contributions":{"hamstrings":1,"glutes":1,"lower_back":0.5,"forearms":0.5}},{"exerciseId":"Seated_Dumbbell_Press","name":"Seated Dumbbell Press","slot":"shoulder_press","pattern":"vertical_push","sets":2,"reps":"8-12","repsMin":8,"repsMax":12,"timed":false,"restSeconds":90,"rir":3,"unilateral":false,"note":null,"alternatives":[{"exerciseId":"Dumbbell_Shoulder_Press","name":"Dumbbell Shoulder Press"},{"exerciseId":"Shoulder_Press_-_With_Bands","name":"Shoulder Press - With Bands"}],"contributions":{"triceps":0.5,"shoulders":0.5}},{"exerciseId":"Dumbbell_Rear_Lunge","name":"Dumbbell Rear Lunge","slot":"quad_unilateral","pattern":"lunge","sets":2,"reps":"8-12 each side","repsMin":8,"repsMax":12,"timed":false,"restSeconds":75,"rir":3,"unilateral":true,"note":null,"alternatives":[{"exerciseId":"Split_Squat_with_Dumbbells","name":"Split Squat with Dumbbells"},{"exerciseId":"Dumbbell_Step_Ups","name":"Dumbbell Step Ups"},{"exerciseId":"Step-up_with_Knee_Raise","name":"Step-up with Knee Raise"}],"contributions":{"quads":1,"glutes":1,"adductors":0.5}},{"exerciseId":"Standing_Dumbbell_Calf_Raise","name":"Standing Dumbbell Calf Raise","slot":"calves","pattern":"calf_raise","sets":3,"reps":"10-15","repsMin":10,"repsMax":15,"timed":false,"restSeconds":60,"rir":3,"unilateral":false,"note":null,"alternatives":[{"exerciseId":"catalog:single-leg-calf-raise","name":"Single-Leg Calf Raise"},{"exerciseId":"catalog:calf-raise","name":"Calf Raise"}],"contributions":{"calves":1}}],"warmup":"About 5 minutes of easy movement, then 1–2 lighter practice sets of the first lift before the working sets.","estimatedMinutes":30}],"volume":[{"group":"chest","label":"Chest","sets":2,"low":4,"high":8,"status":"low","priority":false},{"group":"back","label":"Back (lats & mid-back)","sets":3,"low":4,"high":8,"status":"low","priority":false},{"group":"shoulders","label":"Shoulders (side & rear)","sets":2.5,"low":4,"high":8,"status":"low","priority":false},{"group":"biceps","label":"Biceps","sets":1.5,"low":4,"high":7,"status":"low","priority":false},{"group":"triceps","label":"Triceps","sets":2,"low":4,"high":7,"status":"low","priority":false},{"group":"quads","label":"Quadriceps","sets":4,"low":4,"high":8,"status":"in_range","priority":false},{"group":"hamstrings","label":"Hamstrings","sets":4,"low":4,"high":7,"status":"in_range","priority":false},{"group":"glutes","label":"Glutes","sets":6,"low":4,"high":11,"status":"in_range","priority":false},{"group":"calves","label":"Calves","sets":3,"low":3,"high":6,"status":"in_range","priority":false},{"group":"abs","label":"Abs & obliques","sets":0,"low":3,"high":6,"status":"low","priority":false},{"group":"lower_back","label":"Lower back","sets":1,"low":0,"high":0,"status":"in_range","priority":false},{"group":"forearms","label":"Forearms","sets":1,"low":0,"high":0,"status":"in_range","priority":false},{"group":"adductors","label":"Adductors","sets":2,"low":0,"high":0,"status":"in_range","priority":false}],"progression":[{"week":1,"label":"Learn the plan","setsNote":"Planned sets","rirNote":"One repetition more in reserve than planned while you find your weights"},{"week":2,"label":"Build","setsNote":"Planned sets","rirNote":"Planned reps in reserve; add repetitions where you can"},{"week":3,"label":"Build","setsNote":"Planned sets","rirNote":"Planned reps in reserve; add weight where you hit the top of the range"},{"week":4,"label":"Build","setsNote":"Planned sets","rirNote":"Planned reps in reserve"},{"week":5,"label":"Build (lighter week only if needed)","setsNote":"If you feel run down or performance dropped: about half the sets","rirNote":"Lighter week: easy loads, 4+ repetitions in reserve"},{"week":6,"label":"Re-test and rebuild","setsNote":"Rebuild the plan with your new numbers","rirNote":"Planned reps in reserve"}],"progressionRules":["Double progression: keep the weight until you reach the top of the repetition range on every set at the planned effort, then add the smallest step the equipment allows. Adding repetitions or adding weight both work.","If you can do 1–2 repetitions more than the planned number, increase the load by about 2–10%.","Log every set with its repetitions in reserve. If performance drops for two sessions in a row, or you feel run down, take the lighter week early.","Rebuild the plan every 6–8 weeks, or sooner if your goal, schedule, equipment or health changes."],"cardio":[{"mode":"walking","label":"Brisk or incline walking","minutes":40,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":1,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":40,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":2,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":4,"note":"Moderate effort: you can talk but not sing."},{"mode":"walking","label":"Brisk or incline walking","minutes":35,"intensity":"moderate","exerciseId":"startfit:brisk-walking","weekday":5,"note":"Moderate effort: you can talk but not sing."}],"cardioMinutesPerWeek":150,"cardioTargetMinutes":150,"cardioRamp":[150,150,150,150,150,150],"notes":[{"kind":"adjustment","text":"Chest, Back (lats & mid-back), Shoulders (side & rear), Biceps, Triceps, Abs & obliques are below the weekly target because the sessions are full. More minutes per session or another training day would close the gap."},{"kind":"info","text":"No pull-up or pulldown exercise fits your equipment and limits, so that part is left out."}],"claimIds":["acsm_days","vol_fractional","vol_minimum","vol_session_cap","vol_targets_design","exercise_order","estimate_time","warmup","load_range","failure_optional","rir_start_easier","rir_scale","rest_intervals","freq_hypertrophy","progress_both","progress_increase","deload_concept","deload_rule","who_activity","concurrent","injury_prevention"],"rationale":[{"claimId":"acsm_days","decision":"2 strength days a week, matching the time you have."},{"claimId":"vol_fractional","decision":"Weekly sets are counted as 1 for the main muscle and ½ for helping muscles, and each muscle group gets a target range."},{"claimId":"vol_minimum","decision":"Targets start at about 4 weekly sets per muscle group, the time-efficient minimum, and go higher when time allows."},{"claimId":"exercise_order","decision":"Each session starts with the big multi-joint lifts and ends with smaller single-joint and core exercises."},{"claimId":"warmup","decision":"Every session starts with a short general warm-up and lighter practice sets."},{"claimId":"load_range","decision":"Main lifts use 8–12 repetitions and smaller exercises use higher repetitions; lighter and heavier loads both build muscle."},{"claimId":"failure_optional","decision":"Sets stop about 3 repetitions short of failure on the main lifts; training to failure is not required."},{"claimId":"rest_intervals","decision":"Rest about 1.5 minutes after main-lift sets and 60 seconds after smaller exercises."},{"claimId":"freq_hypertrophy","decision":"Each major muscle group is trained on at least two days, spreading the weekly sets so each session stays manageable."},{"claimId":"progress_both","decision":"Progress by adding repetitions first, then weight (double progression)."},{"claimId":"progress_increase","decision":"Load increases of about 2–10% once you can do 1–2 repetitions more than planned."},{"claimId":"deload_concept","decision":"A lighter week is planned as an option, used when tiredness or performance call for it."},{"claimId":"who_activity","decision":"150 minutes of cardio a week, inside the WHO range of 150–300."},{"claimId":"concurrent","decision":"Cardio goes on other days or at least a few hours away from lifting where possible, so it does not blunt your strength sessions."},{"claimId":"injury_prevention","decision":"Strength work is kept in every week; it was linked to fewer sports injuries, stretching alone was not."}],"inputs":{"goal":"general","experience":"new","daysPerWeek":2,"sessionMinutes":30,"equipment":["bodyweight","dumbbell","band","bench","box"],"age":30,"pain":[],"priorityMuscles":[],"currentActivity":"regular","screeningStatus":"ok"}}'::jsonb, 'library')
